/** The whole look of a Textarea as Tailwind classes. The element itself is the field. */
export const textareaClass =
	"rx-control rx-field block min-h-24 w-full resize-y rounded-(--radius-control) px-[9px] py-[7px] text-[13px]/5 outline-none placeholder:text-(--subtle-foreground) disabled:placeholder:text-(--disabled-foreground)";

"use client";

import { type Ref, type TextareaHTMLAttributes, useContext } from "react";
import { FieldContext } from "./field-context";
import { cn } from "@/lib/utils";
import { textareaClass } from "./textarea.styles";

export type TextareaProps = TextareaHTMLAttributes<HTMLTextAreaElement> & {
	ref?: Ref<HTMLTextAreaElement>;
};

/**
 * A native `<textarea>` drawn as a field. Put it in a `Field` to get a label, a hint and an error
 * wired up, or give it an `aria-label`. `aria-invalid` turns the edge red.
 */
export function Textarea({ className, ...rest }: TextareaProps) {
	const field = useContext(FieldContext);

	return (
		<textarea
			id={field?.id}
			aria-describedby={field?.describedBy}
			aria-invalid={field?.invalid || undefined}
			{...rest}
			className={cn(textareaClass, className)}
		/>
	);
}
